target.css:
:root {
  --ink: #25313a;
  --paper: #fffdf7;
  --sun: #f5c84c;
  --mist: #dce8e7;
  --leaf: #397267;
}

.claim-tag {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--ink);
  background-color: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
}

.claim-tag header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background-color: var(--sun);
  border-bottom: 2px solid var(--ink);
}

.title-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.desk-mark {
  font-size: 26px;
  font-weight: 700;
  line-height: 1;
}

h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1;
}

.status {
  padding: 4px 8px;
  color: var(--paper);
  background-color: var(--leaf);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.item-details {
  padding: 13px 14px;
  background-color: var(--paper);
}

.item-name,
.location {
  margin: 0;
}

.item-name {
  font-size: 16px;
  font-weight: 700;
}

.location {
  margin-top: 3px;
  font-size: 13px;
}

.claim-tag footer {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 14px;
  background-color: var(--mist);
  border-top: 1px solid var(--ink);
}

.claim-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

strong {
  font-size: 15px;
  letter-spacing: 0.04em;
}

button {
  margin-left: auto;
  padding: 6px 10px;
  color: var(--paper);
  background-color: var(--ink);
  border: 0;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}
